def count_files_in_workspace(extension: str = None) -> str:
    from pathlib import Path
    workspace_root = Path(r"D:\AI_Project\mellow_link\workspace")
    count = 0
    if extension:
        for file_path in workspace_root.rglob(f"*.{extension.lstrip('.')}"):
            if file_path.is_file():
                count += 1
    else:
        for file_path in workspace_root.rglob("*"):
            if file_path.is_file():
                count += 1
    return f"[완료] 워크스페이스 파일 개수: {count}개" + (f" (확장자: .{extension})" if extension else "")
